type_pretty:
∀ {V : Type u_1} [inst : Fintype V] [DecidableEq V] (G : SimpleGraph V) [inst_2 : DecidableRel G.Adj],
  0 < G.minDegree →
    Even G.maxDegree →
      have D := G.maxDegree;
      have i := G.indepDominationNumber;
      have n := Fintype.card V;
      (D + 2) ^ 2 * i ≤ (D ^ 2 + 4) * n
